import{_ as i,o as t,c as a,a0 as l}from"./chunks/framework.DQOulFGV.js";const e="data:image/svg+xml;base64,",g="data:image/svg+xml;base64,",d="data:image/svg+xml;base64,",C=JSON.parse('{"title":"第4章 缓存一致性","description":"","frontmatter":{},"headers":[],"relativePath":"redis/03-cache-engineering/chapter-04-consistency.md","filePath":"redis/03-cache-engineering/chapter-04-consistency.md"}'),m={name:"redis/03-cache-engineering/chapter-04-consistency.md"};function Z(c,I,j,s,n,M){return t(),a("div",null,[...I[0]||(I[0]=[l(`<h1 id="第4章-缓存一致性" tabindex="-1">第4章 缓存一致性 <a class="header-anchor" href="#第4章-缓存一致性" aria-label="Permalink to &quot;第4章 缓存一致性&quot;">​</a></h1><blockquote><p>缓存与数据库是两份数据，如何保证它们一致，是缓存架构的核心难题。本章讲解几种写方案、主流的 Cache Aside 模式、延迟双删，以及基于 Binlog 的最终一致性方案。</p></blockquote><hr><h2 id="_4-1-四种写方案" tabindex="-1">4.1 四种写方案 <a class="header-anchor" href="#_4-1-四种写方案" aria-label="Permalink to &quot;4.1 四种写方案&quot;">​</a></h2><p>缓存更新策略有四种经典模式：</p><table tabindex="0"><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">读写流程</th><th style="text-align:left;">特点</th></tr></thead><tbody><tr><td style="text-align:left;">Cache Aside</td><td style="text-align:left;">应用先写数据库，再删缓存</td><td style="text-align:left;">主流，简单可控</td></tr><tr><td style="text-align:left;">Read Through</td><td style="text-align:left;">读时缓存自己查库并填充</td><td style="text-align:left;">缓存层封装了读逻辑</td></tr><tr><td style="text-align:left;">Write Through</td><td style="text-align:left;">写时缓存自己同步写库</td><td style="text-align:left;">缓存层封装了写逻辑</td></tr><tr><td style="text-align:left;">Write Behind</td><td style="text-align:left;">写时只写缓存，异步刷库</td><td style="text-align:left;">性能高，但可能丢数据</td></tr></tbody></table><p>其中 Cache Aside（旁路缓存）是最常见、最可控的方案，其余几种要求缓存层实现更复杂的逻辑。</p><hr><h2 id="_4-2-cache-aside" tabindex="-1">4.2 Cache Aside <a class="header-anchor" href="#_4-2-cache-aside" aria-label="Permalink to &quot;4.2 Cache Aside&quot;">​</a></h2><p>Cache Aside 的核心规则：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读：先查缓存，命中返回；未命中查库，回填缓存</span></span>
<span class="line"><span>写：先更新数据库，再删除缓存</span></span></code></pre></div><p><img src="`+e+`" alt="Cache Aside 读写流程"></p><h3 id="为什么删缓存而不是更新缓存" tabindex="-1">为什么删缓存而不是更新缓存 <a class="header-anchor" href="#为什么删缓存而不是更新缓存" aria-label="Permalink to &quot;为什么删缓存而不是更新缓存&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">问题</th></tr></thead><tbody><tr><td style="text-align:left;">更新缓存</td><td style="text-align:left;">并发写可能覆盖，且很多更新是无用的（写了没人读）</td></tr><tr><td style="text-align:left;">删除缓存</td><td style="text-align:left;">简单安全，下次读时按需回填，天然「懒加载」</td></tr></tbody></table><p>删除缓存避免了「更新缓存」的并发覆盖问题，也避免了缓存那些从未被读取的数据。</p><h3 id="为什么先更新数据库再删缓存" tabindex="-1">为什么先更新数据库再删缓存 <a class="header-anchor" href="#为什么先更新数据库再删缓存" aria-label="Permalink to &quot;为什么先更新数据库再删缓存&quot;">​</a></h3><p>先删缓存再更新数据库，存在「删缓存后、数据库还没更新完，此时有读请求回填旧值」的窗口；先更新数据库再删缓存，把「旧值回填」的窗口缩到最小。两者都无法做到绝对一致，但「先更新库、后删缓存」更接近正确。</p><hr><h2 id="_4-3-延迟双删" tabindex="-1">4.3 延迟双删 <a class="header-anchor" href="#_4-3-延迟双删" aria-label="Permalink to &quot;4.3 延迟双删&quot;">​</a></h2><p>延迟双删用于进一步缩小「先删缓存再更新库」方案的并发窗口，或兜底删除失败的情况。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 删除缓存</span></span>
<span class="line"><span>2. 更新数据库</span></span>
<span class="line"><span>3. 延迟一小段时间（如 500ms）</span></span>
<span class="line"><span>4. 再次删除缓存</span></span></code></pre></div><p><img src="`+g+'" alt="延迟双删流程"></p><p>要点：</p><table tabindex="0"><thead><tr><th style="text-align:left;">要点</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">第二次删除</td><td style="text-align:left;">兜底清理「并发读回填的旧值」</td></tr><tr><td style="text-align:left;">延迟时间</td><td style="text-align:left;">略大于业务读操作耗时</td></tr><tr><td style="text-align:left;">本质</td><td style="text-align:left;">降低概率，非绝对一致</td></tr></tbody></table><blockquote><p>延迟双删只是把不一致的概率降到很低，并不能保证绝对一致。若要绝对一致，需要引入分布式锁或消息队列串行化读写。</p></blockquote><hr><h2 id="_4-4-canal-方案" tabindex="-1">4.4 Canal 方案 <a class="header-anchor" href="#_4-4-canal-方案" aria-label="Permalink to &quot;4.4 Canal 方案&quot;">​</a></h2><p>对于强一致需求的场景，可以基于数据库 Binlog 实现异步同步。</p><p><img src="'+d+'" alt="Canal 同步方案流程"></p><p>Canal 模拟 MySQL 从库，订阅主库的 Binlog，解析出数据变更事件，再投递到消息队列，由消费端更新或删除缓存。</p><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">解耦</td><td style="text-align:left;">缓存更新逻辑与业务代码解耦</td></tr><tr><td style="text-align:left;">最终一致</td><td style="text-align:left;">异步同步，存在秒级延迟</td></tr><tr><td style="text-align:left;">可靠</td><td style="text-align:left;">消息队列保证投递，可重试</td></tr></tbody></table><p>适用场景：对一致性要求较高、且能接受秒级延迟的业务；希望把缓存更新从业务代码中剥离的架构。</p>',32)])])}const p=i(m,[["render",Z]]);export{C as __pageData,p as default};
